const { test } = require("node:test");
const assert = require("node:assert/strict");

const API = process.env.DISCOVERY_API_URL || "http://localhost:3001";
const SEED_PASSWORD = "discovery-only-password";

function extractCookie(res) {
  const cookies = typeof res.headers.getSetCookie === "function" ? res.headers.getSetCookie() : [];
  if (cookies.length) return cookies.map((c) => c.split(";")[0]).join("; ");
  const single = res.headers.get("set-cookie");
  return single ? single.split(";")[0] : "";
}

async function login(username) {
  const res = await fetch(`${API}/login`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ username, password: SEED_PASSWORD }),
  });
  assert.equal(res.status, 200, `login for ${username} should succeed`);
  return extractCookie(res);
}

async function checkAuth(cookie) {
  const res = await fetch(`${API}/checkAuth`, { headers: { Cookie: cookie } });
  assert.equal(res.status, 200, "session should be authenticated");
  const body = await res.json();
  return body.user.id;
}

test("bank account owner can read own account but an unrelated authenticated reader is denied", async () => {
  const seedRes = await fetch(`${API}/testData/seed`, { method: "POST" });
  assert.equal(seedRes.status, 200);

  const usersRes = await fetch(`${API}/testData/users`);
  assert.equal(usersRes.status, 200);
  const { results: users } = await usersRes.json();

  const accountsRes = await fetch(`${API}/testData/bankaccounts`);
  assert.equal(accountsRes.status, 200);
  const { results: accounts } = await accountsRes.json();

  const account = accounts.find((a) => a.isDeleted === false);
  assert.ok(account, "expected a nondeleted seeded bank account");

  const owner = users.find((u) => u.id === account.userId);
  assert.ok(owner, "expected the account owner to exist in seeded users");

  const reader = users.find((u) => u.id !== account.userId);
  assert.ok(reader, "expected a different seeded user to act as an unrelated reader");

  // Owner control: log in as the owner and confirm the exact fixture is readable.
  const ownerCookie = await login(owner.username);
  const ownerId = await checkAuth(ownerCookie);
  assert.equal(ownerId, owner.id);

  const ownerReadRes = await fetch(`${API}/bankAccounts/${account.id}`, {
    headers: { Cookie: ownerCookie },
  });
  assert.equal(ownerReadRes.status, 200, "owner should be able to read their own bank account");
  const ownerReadBody = await ownerReadRes.json();
  assert.equal(ownerReadBody.account.id, account.id);
  assert.equal(ownerReadBody.account.userId, owner.id);

  await checkAuth(ownerCookie);

  // Unrelated reader: a distinct seeded session, authenticated, not the owner.
  const readerCookie = await login(reader.username);
  const readerId = await checkAuth(readerCookie);
  assert.equal(readerId, reader.id);
  assert.notEqual(readerId, account.userId);

  const readerReadRes = await fetch(`${API}/bankAccounts/${account.id}`, {
    headers: { Cookie: readerCookie },
  });

  // Expected (secure) behavior: the unrelated reader is denied with a
  // resource-free error, not shown the owner's bank account record.
  assert.ok(
    [401, 403, 404].includes(readerReadRes.status),
    `expected a denial status for an unrelated reader, got ${readerReadRes.status}`
  );
  const readerReadBody = await readerReadRes.json();
  const keys = Object.keys(readerReadBody);
  assert.deepEqual(keys, ["error"], "denial body must be error-only JSON");
  assert.ok(
    ["Unauthorized", "Forbidden", "Not Found", "denied"].includes(readerReadBody.error),
    `unexpected denial message: ${readerReadBody.error}`
  );

  await checkAuth(readerCookie);
});

