test("private transaction participants can read it but an unrelated authenticated reader is denied", async () => {
  const seedRes = await fetch(`${API}/testData/seed`, { method: "POST" });
  assert.equal(seedRes.status, 200);

  const usersRes = await fetch(`${API}/testData/users`);
  assert.equal(usersRes.status, 200);
  const { results: users } = await usersRes.json();

  const contactsRes = await fetch(`${API}/testData/contacts`);
  assert.equal(contactsRes.status, 200);
  const { results: contacts } = await contactsRes.json();

  const transactionsRes = await fetch(`${API}/testData/transactions`);
  assert.equal(transactionsRes.status, 200);
  const { results: transactions } = await transactionsRes.json();

  const privateTxn = transactions.find((t) => t.privacyLevel === "private");
  assert.ok(privateTxn, "expected a seeded private transaction");

  const sender = users.find((u) => u.id === privateTxn.senderId);
  const receiver = users.find((u) => u.id === privateTxn.receiverId);
  assert.ok(sender && receiver, "expected both transaction participants to exist");

  // An unrelated reader: not a participant and not a contact of either participant.
  const relatedIds = new Set([
    sender.id,
    receiver.id,
    ...contacts
      .filter((c) => c.userId === sender.id || c.userId === receiver.id)
      .map((c) => c.contactUserId),
    ...contacts
      .filter((c) => c.contactUserId === sender.id || c.contactUserId === receiver.id)
      .map((c) => c.userId),
  ]);
  const reader = users.find((u) => !relatedIds.has(u.id));
  assert.ok(reader, "expected a seeded user unrelated to the private transaction");

  // Participant controls: both sender and receiver can legitimately read the record.
  for (const participant of [sender, receiver]) {
    const cookie = await login(participant.username);
    const id = await checkAuth(cookie);
    assert.equal(id, participant.id);

    const res = await fetch(`${API}/transactions/${privateTxn.id}`, {
      headers: { Cookie: cookie },
    });
    assert.equal(res.status, 200, "participant should be able to read the private transaction");
    const body = await res.json();
    assert.equal(body.transaction.id, privateTxn.id);
    assert.equal(body.transaction.privacyLevel, "private");

    await checkAuth(cookie);
  }

  // Unrelated reader: a distinct seeded session, authenticated, not a participant or contact.
  const readerCookie = await login(reader.username);
  const readerId = await checkAuth(readerCookie);
  assert.equal(readerId, reader.id);
  assert.notEqual(readerId, sender.id);
  assert.notEqual(readerId, receiver.id);

  const readerReadRes = await fetch(`${API}/transactions/${privateTxn.id}`, {
    headers: { Cookie: readerCookie },
  });

  // Expected (secure) behavior: the unrelated reader is denied with a
  // resource-free error, not shown the private transaction record.
  assert.ok(
    [401, 403, 404].includes(readerReadRes.status),
    `expected a denial status for an unrelated reader, got ${readerReadRes.status}`
  );
  const readerReadBody = await readerReadRes.json();
  const keys = Object.keys(readerReadBody);
  assert.deepEqual(keys, ["error"], "denial body must be error-only JSON");
  assert.ok(
    ["Unauthorized", "Forbidden", "Not Found", "denied"].includes(readerReadBody.error),
    `unexpected denial message: ${readerReadBody.error}`
  );

  await checkAuth(readerCookie);
});

